/**
 * A static stand-in for `motion/react`, so the vendored mdx-graphs components
 * render as characters and nothing else.
 *
 * Upstream every graph animates: rows stagger in on `whileInView`, glyphs fade
 * up from `initial={{ opacity: 0 }}`. That is a runtime behaviour, and these
 * graphs have no runtime — they are rendered at build time through the React
 * integration with no client directive, so no hydration ever arrives to raise
 * the opacity motion wrote into the markup. Shipping the real library would
 * mean shipping the animation runtime with it, on a page whose whole argument
 * is that a chart can be text.
 *
 * So the graphs take the path the library already has for a reader who does not
 * want motion. `useReducedMotion()` answers true, and every component's own
 * reduced-motion branch resolves its variants to the finished state, skips the
 * `initial` frame, and sets the transitions to zero. `motion.<tag>` is then just
 * `<tag>` with the animation props dropped — `style` and `className` pass
 * through, because two of the components carry real dimming in `style`.
 *
 * Keeping the shim here rather than editing the components means a re-vendor
 * from the registry is a copy plus two import rewrites, not a re-application of
 * hand edits.
 */

import * as React from "react";

/** Structural stubs for the two types graph-motion.ts imports for its helpers. */
export type Transition = Record<string, unknown>;
export type Variants = Record<string, Record<string, unknown>>;

/**
 * Props that only mean something to the animation runtime. Everything else —
 * className, style, role, aria-*, key, children — is forwarded to the DOM.
 */
const MOTION_PROPS = new Set([
  "animate",
  "custom",
  "drag",
  "exit",
  "initial",
  "layout",
  "layoutId",
  "onAnimationComplete",
  "onAnimationStart",
  "transition",
  "variants",
  "viewport",
  "whileDrag",
  "whileFocus",
  "whileHover",
  "whileInView",
  "whileTap",
]);

function strip(props: Record<string, unknown>) {
  const out: Record<string, unknown> = {};
  for (const key in props) {
    if (!MOTION_PROPS.has(key)) out[key] = props[key];
  }
  return out;
}

type MotionTags = {
  [K in keyof React.JSX.IntrinsicElements]: React.FC<
    React.JSX.IntrinsicElements[K] & Record<string, unknown>
  >;
};

/**
 * `motion.div`, `motion.li`, … resolved on demand. A Proxy rather than a fixed
 * map so a component vendored later cannot reach for a tag the shim forgot.
 */
export const motion = new Proxy({} as MotionTags, {
  get(cache: Record<string, unknown>, tag: string) {
    if (!cache[tag]) {
      const Component = (props: Record<string, unknown>) =>
        React.createElement(tag, strip(props));
      Component.displayName = `motion.${tag}`;
      cache[tag] = Component;
    }
    return cache[tag];
  },
}) as MotionTags;

/**
 * Always true. Not a claim about the reader's `prefers-reduced-motion` — it is
 * the honest answer for a page that ships no animation runtime at all.
 */
export function useReducedMotion(): boolean {
  return true;
}

"use client"

import { cn } from "@/lib/utils"

function GraphArrow({
  accent = false,
  stretch = false,
  className,
}: {
  accent?: boolean
  stretch?: boolean
  className?: string
}) {
  return (
    <div
      aria-hidden="true"
      className={cn(
        "flex min-w-6 items-center gap-1",
        stretch && "min-w-10 flex-1",
        accent ? "text-graph-accent" : "text-graph-frame",
        className
      )}
    >
      {stretch ? (
        <span className="h-px min-w-6 flex-1 border-t border-dashed border-current" />
      ) : (
        <span>- - -</span>
      )}
      <span className="shrink-0">▶</span>
    </div>
  )
}

export { GraphArrow }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

function GraphCorners({ mark = "+" }: { mark?: string }) {
  return (
    <>
      <span
        aria-hidden="true"
        className="pointer-events-none absolute top-0 left-0 z-10 block -translate-x-1/2 -translate-y-1/2 bg-background px-0.5 text-graph-frame"
      >
        {mark}
      </span>
      <span
        aria-hidden="true"
        className="pointer-events-none absolute top-0 right-0 z-10 block translate-x-1/2 -translate-y-1/2 bg-background px-0.5 text-graph-frame"
      >
        {mark}
      </span>
      <span
        aria-hidden="true"
        className="pointer-events-none absolute bottom-0 left-0 z-10 block -translate-x-1/2 translate-y-1/2 bg-background px-0.5 text-graph-frame"
      >
        {mark}
      </span>
      <span
        aria-hidden="true"
        className="pointer-events-none absolute right-0 bottom-0 z-10 block translate-x-1/2 translate-y-1/2 bg-background px-0.5 text-graph-frame"
      >
        {mark}
      </span>
    </>
  )
}

function GraphTitle({
  className,
  children,
  ...props
}: React.ComponentProps<"figcaption">) {
  return (
    <figcaption
      className={cn(
        "absolute top-0 left-1/2 z-10 -translate-x-1/2 -translate-y-1/2 bg-background px-2.5 tracking-wide whitespace-nowrap uppercase",
        className
      )}
      {...props}
    >
      <span className="graph-title-ink text-graph-accent">[ {children} ]</span>
    </figcaption>
  )
}

function GraphBody({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div className={cn("px-5 py-7 sm:px-8 sm:py-8", className)} {...props} />
  )
}

function GraphRule({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      aria-hidden="true"
      className={cn("graph-rule w-full", className)}
      {...props}
    />
  )
}

function GraphTrack({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      aria-hidden="true"
      className={cn("flex w-full min-w-0 select-none", className)}
      {...props}
    />
  )
}

function GraphTick({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      className={cn("min-w-[1ch] flex-1 text-center", className)}
      {...props}
    />
  )
}

function Graph({
  title,
  corner = "+",
  className,
  children,
  ...props
}: React.ComponentProps<"figure"> & {
  title?: string
  corner?: string
}) {
  const captionId = React.useId()

  return (
    <figure
      aria-labelledby={title ? captionId : undefined}
      className={cn(
        "relative min-w-0 graph-frame font-mono text-sm text-foreground",
        className
      )}
      {...props}
    >
      {title ? <GraphTitle id={captionId}>{title}</GraphTitle> : null}
      <GraphCorners mark={corner} />
      {children}
    </figure>
  )
}

export {
  Graph,
  GraphBody,
  GraphCorners,
  GraphRule,
  GraphTick,
  GraphTitle,
  GraphTrack,
}

import type { Transition, Variants } from "@/registry/default/motion-static/motion-static"

export const easeOutCubic = [0.215, 0.61, 0.355, 1] as const

/**
 * Upstream 0.4. This site holds every piece of text to 4.5:1, and at 40%
 * opacity nothing clears it: the muted grey is only at 5.1:1 to begin with,
 * and even full-strength foreground text falls to about 2.8:1. So nothing is
 * dimmed here — the accent alone marks the row or column being pointed at,
 * which is the argument the section is making anyway. Colour marks; it does
 * not have to shout the rest down.
 */
export const DIM_OPACITY = 1

export function graphTransition(
  reduce: boolean | null,
  extras?: Transition
): Transition {
  if (reduce) {
    return { duration: 0 }
  }

  return {
    duration: 0.22,
    ease: easeOutCubic,
    ...extras,
  }
}

export function fadeUp(reduce: boolean | null): Variants {
  if (reduce) {
    return {
      hidden: { opacity: 1, transform: "translateY(0px)" },
      show: { opacity: 1, transform: "translateY(0px)" },
    }
  }

  return {
    hidden: { opacity: 0, transform: "translateY(8px)" },
    show: {
      opacity: 1,
      transform: "translateY(0px)",
      transition: graphTransition(false),
    },
  }
}

export function staggerList(reduce: boolean | null, stagger = 0.04): Variants {
  return {
    hidden: {},
    show: {
      transition: reduce ? { duration: 0 } : { staggerChildren: stagger },
    },
  }
}

export function fillDelay(reduce: boolean | null, index: number, step = 0.03) {
  if (reduce) {
    return 0
  }

  return Math.min(index * step, 0.28)
}

export function clamp01(value: number) {
  return Math.min(1, Math.max(0, value))
}

export const GLYPH_SETS = {
  shade: ["·", "░", "▒", "▓", "█"],
  ascii: [".", "-", "=", "#", "@"],
  hash: [".", ":", "+", "#", "█"],
  bar: ["▁", "▂", "▃", "▅", "█"],
} as const

export type GlyphSetName = keyof typeof GLYPH_SETS
export type Glyphs = GlyphSetName | readonly string[]

export const INTENSITY_GLYPHS = GLYPH_SETS.shade

export function resolveGlyphs(glyphs?: Glyphs): readonly string[] {
  if (glyphs == null) {
    return GLYPH_SETS.shade
  }

  if (typeof glyphs === "string") {
    return GLYPH_SETS[glyphs] ?? GLYPH_SETS.shade
  }

  return glyphs.length > 0 ? glyphs : GLYPH_SETS.shade
}

export function trackMarks(
  glyphs?: Glyphs,
  fallback: { empty: string; rest: string; fill: string } = {
    empty: "-",
    rest: "░",
    fill: "█",
  }
) {
  if (glyphs == null) {
    return fallback
  }

  const set = resolveGlyphs(glyphs)
  const last = set.length - 1

  return {
    empty: set[0] ?? fallback.empty,
    rest: set[Math.min(1, last)] ?? fallback.rest,
    fill: set[last] ?? fallback.fill,
  }
}

export function intensityLevel(value: number, max: number) {
  if (value <= 0 || max <= 0) {
    return 0
  }

  return Math.max(1, Math.round(clamp01(value / max) * 4))
}

export function intensityGlyph(
  level: number,
  glyphs: readonly string[] = INTENSITY_GLYPHS
) {
  if (glyphs.length === 0) {
    return "·"
  }

  const clamped = Math.min(4, Math.max(0, Math.round(level)))
  const index = Math.round((clamped / 4) * (glyphs.length - 1))
  return glyphs[index] ?? glyphs[0] ?? "·"
}

export function intensityClass(level: number, palette: GraphPalette = "mono") {
  const index = Math.min(4, Math.max(0, Math.round(level)))

  if (index <= 0) {
    return "text-graph-frame"
  }

  if (palette === "mono") {
    if (index <= 2) {
      return "text-graph-muted"
    }

    if (index === 3) {
      return "text-foreground"
    }

    return "text-graph-accent"
  }

  if (palette === "multi") {
    if (index === 1) {
      return "text-graph-accent-2"
    }

    if (index <= 3) {
      return "text-graph-accent-3"
    }

    return "text-graph-accent"
  }

  if (index <= 2) {
    return "text-graph-accent-2"
  }

  return "text-graph-accent"
}

export type GraphPalette = "mono" | "duo" | "multi"

const SERIES_TONES = [
  "text-graph-accent",
  "text-graph-accent-2",
  "text-graph-accent-3",
] as const

export function isMonoPalette(palette?: GraphPalette) {
  return palette == null || palette === "mono"
}

export function seriesClass(palette: GraphPalette | undefined, index: number) {
  if (isMonoPalette(palette)) {
    return index === 0 ? "text-graph-accent" : "text-foreground"
  }

  const count = palette === "duo" ? 2 : 3
  return SERIES_TONES[index % count]
}

export function seriesDim(
  palette: GraphPalette | undefined,
  highlighted: boolean
) {
  if (!isMonoPalette(palette) || highlighted) {
    return undefined
  }

  return { opacity: DIM_OPACITY }
}

export function toneClass(
  palette: GraphPalette | undefined,
  role: "primary" | "secondary" | "idle" | "empty"
) {
  if (role === "empty") {
    return "text-graph-frame"
  }

  if (role === "idle") {
    return "text-graph-muted"
  }

  if (role === "primary") {
    return "text-graph-accent"
  }

  return isMonoPalette(palette) ? "text-graph-muted" : "text-graph-accent-2"
}

"use client"

import { motion, useReducedMotion } from "@/registry/default/motion-static/motion-static"

import { GraphArrow } from "@/registry/default/graph-arrow/graph-arrow"
import { Graph, GraphBody } from "@/registry/default/graph-frame/graph-frame"
import {
  fadeUp,
  staggerList,
  toneClass as paletteTone,
  type GraphPalette,
} from "@/registry/default/graph-motion/graph-motion"
import { cn } from "@/lib/utils"

type FlowTone = "default" | "accent" | "muted"

type FlowNode = {
  label: string
  tone?: FlowTone
  stretch?: boolean
}

type FlowRow = {
  nodes: FlowNode[]
}

type GraphFlowProps = {
  title: string
  rows: FlowRow[]
  palette?: GraphPalette
  corner?: string
  className?: string
}

function nodeTone(palette: GraphPalette | undefined): Record<FlowTone, string> {
  return {
    default: "text-foreground",
    accent: paletteTone(palette, "primary"),
    muted: paletteTone(palette, "secondary"),
  }
}

function GraphFlow({
  title,
  rows,
  palette,
  corner,
  className,
}: GraphFlowProps) {
  const reduce = useReducedMotion()
  const item = fadeUp(reduce)
  const list = staggerList(reduce, 0.08)
  const tones = nodeTone(palette)

  return (
    <Graph title={title} className={className} corner={corner}>
      <GraphBody className="flex flex-col gap-7">
        <motion.div
          className="flex flex-col gap-7"
          initial={reduce ? false : "hidden"}
          variants={list}
          viewport={{ once: true, amount: 0.5 }}
          whileInView="show"
        >
          {rows.map((row, rowIndex) => (
            <motion.div
              key={rowIndex}
              className="flex min-w-0 flex-wrap items-center gap-x-3 gap-y-2 sm:flex-nowrap"
              variants={item}
            >
              {row.nodes.map((node, nodeIndex) => {
                const tone = node.tone ?? "default"
                const live = tone === "accent"

                return (
                  <div
                    key={`${node.label}-${nodeIndex}`}
                    className={cn(
                      "flex min-w-0 items-center gap-3",
                      node.stretch && "min-w-16 flex-1"
                    )}
                  >
                    {nodeIndex > 0 ? (
                      <GraphArrow accent={live} stretch={node.stretch} />
                    ) : null}
                    <span
                      className={cn("shrink-0 whitespace-nowrap", tones[tone])}
                    >
                      {node.label}
                    </span>
                  </div>
                )
              })}
            </motion.div>
          ))}
        </motion.div>
      </GraphBody>
    </Graph>
  )
}

export { GraphFlow }
export type { FlowNode, FlowRow, GraphFlowProps }
